from __future__ import annotations

import hashlib
import json
from pathlib import Path

import pytest

from tfx_quant.packaging import build_support as bs

_LOCK_SNIPPET = """\
#
# autogenerated
#
annotated-types==0.8.0 \\
    --hash=sha256:13b2beaad985e05e2d6407ee4c4f35590b11f8d693a258a561055cac8f64cab7 \\
    --hash=sha256:f072f4d804ea359e4eaf198b1af7a8b0943881a87f31bb764f8bf219bb9419e0
    # via pydantic
comtypes==1.4.16 \\
    --hash=sha256:cd66d1add01265cface4df51ba1e31cd1657e04463c281c802e737e79e1ba93c
    # via -r installer/requirements.in
"""


def test_sha256_and_verify(tmp_path: Path) -> None:
    f = tmp_path / "x.bin"
    f.write_bytes(b"hello")
    digest = hashlib.sha256(b"hello").hexdigest()
    assert bs.sha256_file(f) == digest
    bs.verify_sha256(f, digest.upper())  # case-insensitive
    with pytest.raises(bs.BuildError):
        bs.verify_sha256(f, "0" * 64)


def test_parse_requirements_lock() -> None:
    entries = bs.parse_requirements_lock(_LOCK_SNIPPET)
    assert [e["name"] for e in entries] == ["annotated-types", "comtypes"]
    assert entries[0]["version"] == "0.8.0"
    assert len(entries[0]["hashes"]) == 2
    assert len(entries[1]["hashes"]) == 1


def test_write_sha256sums(tmp_path: Path) -> None:
    stage = tmp_path / "app"
    (stage / "sub").mkdir(parents=True)
    (stage / "a.txt").write_text("a", encoding="utf-8")
    (stage / "sub" / "b.txt").write_text("b", encoding="utf-8")
    out = stage / "SHA256SUMS"
    count = bs.write_sha256sums(stage, out)
    assert count == 2
    lines = out.read_text(encoding="utf-8").splitlines()
    assert any(line.endswith("  a.txt") for line in lines)
    assert any(line.endswith("  sub/b.txt") for line in lines)
    assert not any("SHA256SUMS" in line for line in lines)


def test_license_inventory_and_text(tmp_path: Path) -> None:
    sp = tmp_path / "site-packages"
    di = sp / "wombat-1.2.3.dist-info"
    di.mkdir(parents=True)
    (di / "METADATA").write_text(
        "Name: wombat\nVersion: 1.2.3\nLicense: MIT\n\nbody\n", encoding="utf-8"
    )
    (di / "LICENSE").write_text("MIT text", encoding="utf-8")
    inventory = bs.collect_license_inventory(sp)
    assert inventory == [
        {"name": "wombat", "version": "1.2.3", "license": "MIT", "license_files": "LICENSE"}
    ]
    text = bs.render_license_text(inventory)
    assert "wombat 1.2.3 — MIT" in text
    assert "不隨本安裝檔散布" in text  # default: nothing proprietary bundled

    bundled = bs.render_license_text(inventory, vendor_bundled=True)
    assert "專有元件" in bundled and "散布之授權" in bundled
    assert "wombat 1.2.3 — MIT" in bundled


def test_copy_vendor_tree_filters_debug_and_docs(tmp_path: Path) -> None:
    src = tmp_path / "API"
    (src / "sub").mkdir(parents=True)
    for name in (
        "YuantaOrd.ocx",
        "YuantaOrdLib.dll",
        "install_YTFutOrdAP.bat",
        "msvcrtd.dll",  # debug CRT -> skipped
        "元大行情API.pdf",  # doc -> skipped
        "sample.py",  # -> skipped
        "sub/libns.dll",
    ):
        p = src / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(b"x")
    dest = tmp_path / "out"
    n = bs.copy_vendor_tree(src, dest)
    got = {p.relative_to(dest).as_posix() for p in dest.rglob("*") if p.is_file()}
    assert got == {
        "YuantaOrd.ocx",
        "YuantaOrdLib.dll",
        "install_YTFutOrdAP.bat",
        "sub/libns.dll",
    }
    assert n == 4


def test_copy_vendor_tree_missing_src_raises(tmp_path: Path) -> None:
    with pytest.raises(bs.BuildError):
        bs.copy_vendor_tree(tmp_path / "nope", tmp_path / "out")


