def test_render_release_notes_substitutes_and_preserves_unknown() -> None:
    out = bs.render_release_notes(
        "v{{ version }} rev {{ source_revision }} extra {{ mystery }}",
        {"version": "0.1.0", "source_revision": "abc123"},
    )
    assert out == "v0.1.0 rev abc123 extra {{ mystery }}"


def test_rewrite_embed_pth(tmp_path: Path) -> None:
    runtime = tmp_path / "runtime"
    runtime.mkdir()
    pth = runtime / "python311._pth"
    pth.write_text("python311.zip\n.\n\n# import site\n", encoding="utf-8")
    bs.rewrite_embed_pth(runtime, ["..\\Lib\\site-packages", "..\\src"])
    lines = pth.read_text(encoding="utf-8").splitlines()
    assert "..\\Lib\\site-packages" in lines
    assert "..\\src" in lines
    assert lines[-1] == "import site"
    assert "# import site" not in lines


def test_rewrite_embed_pth_without_file_raises(tmp_path: Path) -> None:
    with pytest.raises(bs.BuildError):
        bs.rewrite_embed_pth(tmp_path, [])


def test_resolve_python_embed_zip_offline_without_cache(tmp_path: Path) -> None:
    with pytest.raises(bs.BuildError):
        bs.resolve_python_embed_zip(cache_dir=tmp_path, allow_download=False)


def test_resolve_python_embed_zip_uses_verified_cache(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    cache = tmp_path / "cache"
    cache.mkdir()
    zip_path = cache / f"python-{bs.EMBED_PYTHON_VERSION}-embed-win32.zip"
    zip_path.write_bytes(b"pretend-zip")
    monkeypatch.setattr(bs, "EMBED_PYTHON_SHA256", hashlib.sha256(b"pretend-zip").hexdigest())
    assert bs.resolve_python_embed_zip(cache_dir=cache, allow_download=False) == zip_path


def test_build_manifest_shape(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    stage = tmp_path / "app"
    stage.mkdir()
    (stage / "f.txt").write_text("x", encoding="utf-8")
    embed = tmp_path / "python-embed.zip"
    embed.write_bytes(b"zip")
    manifest = bs.build_manifest(
        app_version="0.1.0",
        source_revision="deadbeef",
        source_dirty=False,
        tools=bs.ToolVersions(python="3.11.9", pip="24.0"),
        python_embed_zip=embed,
        requirements_lock_text=_LOCK_SNIPPET,
        stage_dir=stage,
    )
    assert manifest["app_version"] == "0.1.0"
    assert manifest["source_revision"] == "deadbeef"
    assert manifest["python_embed"]["sha256"] == hashlib.sha256(b"zip").hexdigest()
    assert manifest["staged_file_count"] == 1
    assert manifest["vendor_bundle"] is None
    assert {d["name"] for d in manifest["dependencies"]} == {"annotated-types", "comtypes"}
    # must be JSON-serialisable
    json.dumps(manifest)


def test_build_manifest_records_vendor_bundle(tmp_path: Path) -> None:
    stage = tmp_path / "app"
    stage.mkdir()
    embed = tmp_path / "e.zip"
    embed.write_bytes(b"z")
    manifest = bs.build_manifest(
        app_version="0.1.0",
        source_revision="x",
        source_dirty=True,
        tools=bs.ToolVersions(python="3.11.9", pip="24.0"),
        python_embed_zip=embed,
        requirements_lock_text="",
        stage_dir=stage,
        vendor_bundle={
            "redistribution_right_asserted_by_distributor": True,
            "yuanta_trade_api": {},
        },
    )
    assert manifest["vendor_bundle"]["redistribution_right_asserted_by_distributor"] is True
    json.dumps(manifest)


def test_make_release_manifest(tmp_path: Path) -> None:
    exe = tmp_path / "tfx-quant-setup-0.1.0.exe"
    exe.write_bytes(b"MZ...")
    stage_manifest = {"app_version": "0.1.0", "source_revision": "abc", "source_dirty": False}
    rel = bs.make_release_manifest(
        installer_path=exe,
        stage_build_manifest=stage_manifest,
        signed=False,
        signature_subject=None,
    )
    assert rel["installer"]["filename"] == "tfx-quant-setup-0.1.0.exe"
    assert rel["installer"]["sha256"] == hashlib.sha256(b"MZ...").hexdigest()
    assert rel["signature"] == {"signed": False, "subject": None}
    assert rel["app_version"] == "0.1.0"


def test_resolve_source_revision_on_this_repo() -> None:
    repo_root = Path(__file__).resolve().parents[2]
    commit, dirty = bs.resolve_source_revision(repo_root)
    assert len(commit) == 40 or commit == "unknown"
    assert isinstance(dirty, bool)
